def gen(rng):
    def make_tree(m, mode):
        """Distinct sorted values placed into a random-shaped BST; returns (val, left, right) arrays by position in inorder."""
        vals = sorted(rng.sample(range(-60, 61), m)) if m <= 100 else sorted(rng.sample(range(-10**9, 10**9 + 1), m))
        left = [-1] * m
        right = [-1] * m
        root = -1
        stack = [(0, m - 1, -1, 0)]  # lo, hi, parent, side
        while stack:
            lo, hi, par, side = stack.pop()
            if lo > hi:
                continue
            if mode == 'left':
                mid = hi
            elif mode == 'right':
                mid = lo
            elif mode == 'zigzag':
                mid = hi if (hi - lo) % 2 == 0 else lo
            elif mode == 'balanced':
                mid = (lo + hi) // 2
            else:
                mid = rng.randint(lo, hi)
            if par == -1:
                root = mid
            elif side == 0:
                left[par] = mid
            else:
                right[par] = mid
            stack.append((lo, mid - 1, mid, 0))
            stack.append((mid + 1, hi, mid, 1))
        return vals, left, right, root

    def serialize(vals, left, right, root):
        out = []
        queue = [root]
        qi = 0
        while qi < len(queue):
            v = queue[qi]
            qi += 1
            if v == -1:
                out.append('null')
            else:
                out.append(str(vals[v]))
                queue.append(left[v])
                queue.append(right[v])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def ops_list(m, q, style):
        ops = []
        rem = m
        while len(ops) < q:
            if style == 'alt':
                ops.append('hasNext')
                if len(ops) < q and rem > 0:
                    ops.append('next')
                    rem -= 1
            elif rem > 0 and rng.random() < 0.6:
                ops.append('next')
                rem -= 1
            else:
                ops.append('hasNext')
        return ops

    def fmt(m, mode, q, style='rand'):
        vals, left, right, root = make_tree(m, mode)
        ops = ops_list(m, q, style)
        return serialize(vals, left, right, root) + '\n' + str(len(ops)) + '\n' + '\n'.join(ops)

    tests = ['5\n3\nhasNext\nnext\nhasNext', '7 3 15 null null 9 20\n8\nnext\nnext\nhasNext\nnext\nhasNext\nnext\nnext\nhasNext',
             '1\n2\nhasNext\nnext', '1\n3\nnext\nhasNext\nhasNext',
             '2 1\n4\nhasNext\nnext\nnext\nhasNext', '1 null 2\n4\nnext\nnext\nhasNext\nhasNext']
    for m in (1, 2, 3, 5, 8, 12):
        for mode in ('random', 'left', 'right', 'balanced', 'zigzag'):
            if m <= 12 and rng.random() < 0.6:
                tests.append(fmt(m, mode if m > 2 else 'random', rng.randint(m, 2 * m + 2)))
    for m in (4, 6, 9):
        tests.append(fmt(m, 'small', 3 * m, 'alt'))
    tests = [t for t in tests if len(t) <= 380]
    M = 40000
    Q = 10**5
    tests.append(fmt(M, 'random', Q, 'alt'))
    tests.append(fmt(M, 'left', Q, 'alt'))
    tests.append(fmt(M, 'right', Q, 'alt'))
    tests.append(fmt(M, 'balanced', Q, 'rand'))
    tests.append(fmt(M, 'zigzag', Q, 'alt'))
    tests.append(fmt(1, 'random', Q, 'rand'))
    return tests

